SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/biobricks-aopwiki> { ?v1_a <http://www.w3.org/2004/02/skos/core#exactMatch> ?v2_a . FILTER(STRSTARTS(STR(?v2_a),'https://identifiers.org/ensembl/')) } BIND(IRI(REPLACE(STR(?v2_a),'https://identifiers.org/ensembl/','http://identifiers.org/ensembl/')) AS ?key)
  GRAPH <https://purl.org/okn/frink/kg/pankgraph> { ?key a <https://w3id.org/biolink/vocab/Gene> . }
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/biobricks-aopwiki> { ?v1_a <http://aopkb.org/aop_ontology#has_chemical_entity> ?v2_a . } BIND(IRI(REPLACE(STR(?v2_a),'https://identifiers.org/cas/','http://identifiers.org/cas/')) AS ?key)
  GRAPH <https://purl.org/okn/frink/kg/biobricks-ice> { ?v1_b <http://edamontology.org/has_identifier> ?key . }
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/biobricks-aopwiki> { ?v1_a <http://aopkb.org/aop_ontology#has_chemical_entity> ?v2_a . } BIND(IRI(REPLACE(STR(?v2_a),'https://identifiers.org/cas/','http://identifiers.org/cas/')) AS ?key)
  GRAPH <https://purl.org/okn/frink/kg/biobricks-tox21> { ?key ?v1_b ?v2_b . }
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  { SELECT DISTINCT ?key WHERE { GRAPH <https://purl.org/okn/frink/kg/digcfdekg> { ?v1_a <https://purl.org/okn/frink/kg/digcfdekg/schema/geneToTrait> ?key . FILTER(STRSTARTS(STR(?key),'http://www.ebi.ac.uk/efo/EFO_') || STRSTARTS(STR(?key),'http://purl.obolibrary.org/obo/MONDO_') || CONTAINS(STR(?key),'Orphanet_')) } } }
  GRAPH <https://purl.org/okn/frink/kg/nde> { ?v1_b <http://schema.org/healthCondition> ?key . FILTER(STRSTARTS(STR(?key),'http://purl.obolibrary.org/obo/MONDO_')) }
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/biobricks-aopwiki> { ?v1_a <http://purl.org/dc/elements/1.1/identifier> ?key . FILTER(STRSTARTS(STR(?key),'http://purl.obolibrary.org/obo/NCBITaxon_')) }
  { SELECT DISTINCT ?key WHERE { GRAPH <https://purl.org/okn/frink/kg/nde> { ?v1_b <http://schema.org/species> ?v2_b . FILTER(CONTAINS(STR(?v2_b),'/taxonomy/')) } BIND(IRI(CONCAT('http://purl.obolibrary.org/obo/NCBITaxon_',REPLACE(STR(?v2_b),'^.*/taxonomy/([0-9]+).*$','$1'))) AS ?key) } }
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/biobricks-tox21> { ?key ?v1_a ?v2_a . }
  GRAPH <https://purl.org/okn/frink/kg/sockg> { ?v1_b <http://w3id.org/coso/v1/contaminoso#casNumber> ?v2_b . } BIND(IRI(CONCAT('http://identifiers.org/cas/', STR(?v2_b))) AS ?key)
}

SELECT (COUNT(DISTINCT ?key) AS ?n) WHERE {
  GRAPH <https://purl.org/okn/frink/kg/geoconnex> { ?v1_a <http://gnis-ld.org/lod/gnis/ontology/county> ?v2_a . } BIND(REPLACE(STR(?v2_a),'^.*/counties/([0-9]{5}).*$','$1') AS ?v3_a) BIND(IRI(CONCAT('http://stko-kwg.geog.ucsb.edu/lod/resource/administrativeRegion.USA.',?v3_a)) AS ?key)
  GRAPH <https://purl.org/okn/frink/kg/sockg> { ?key a <http://stko-kwg.geog.ucsb.edu/lod/ontology/AdministrativeRegion_2> . }
}
